-- ===== WindUI adapter: maps the existing Window/Tab calls onto WindUI =====
local bearlib = {}

local function pickCallback(Configs, index)
    local f = Configs[index] or Configs.Callback
    if type(f) == "table" then
        return function(Value) f[1][f[2]] = Value end
    end
    if type(f) ~= "function" then return function() end end
    return f
end

local function fire(cb, ...)
    local args = table.pack(...)
    task.spawn(function()
        local ok, err = pcall(cb, table.unpack(args, 1, args.n))
        if not ok then warn("[Bantai Hub v2 UI] callback error: " .. tostring(err)) end
    end)
end

local function sameList(a, b)
    if #a ~= #b then return false end
    for i = 1, #a do
        if a[i] ~= b[i] then return false end
    end
    return true
end

local function copyList(list)
    local out = {}
    for _, v in ipairs(list) do table.insert(out, v) end
    return out
end

function bearlib:Notify(Configs)
    Configs = Configs or {}
    local Icon = Configs.Icon
    if type(Icon) ~= "string" or Icon == "" then Icon = "bell" end
    local ok = pcall(function()
        WindUI:Notify({
            Title = Configs.Title or Configs[1] or "Bantai Hub v2",
            Content = Configs.Message or Configs.Content or Configs.Text or Configs[2] or "",
            Duration = Configs.Duration or Configs.Time or 5,
            Icon = Icon,
        })
    end)
    return ok
end

local KEY_URL = "https://pastebin.com/raw/C9GyQeDK"
local HUB_NAME = "Bantai Hub v2"
local HUB_AUTHOR = "by NotThatAnik"
local Created

local function trim(str)
    return (tostring(str):gsub("^%s+", ""):gsub("%s+$", ""))
end

local function httpGet(url)
    local ok, body = pcall(function() return game:HttpGet(url, true) end)
    if ok and type(body) == "string" and body ~= "" then return body end
    local req = request or http_request or (syn and syn.request)
    if req then
        local ok2, res = pcall(req, {Url = url, Method = "GET"})
        if ok2 and type(res) == "table" and type(res.Body) == "string" and res.Body ~= "" then
            return res.Body
        end
    end
    return nil
end

local function fetchKeys()
    local body
    for _ = 1, 3 do
        body = httpGet(KEY_URL)
        if body then break end
        task.wait(1)
    end
    if not body then return nil end
    local keys = {}
    for line in body:gmatch("[^\r\n]+") do
        local k = trim(line)
        if k ~= "" then keys[k] = true end
    end
    if next(keys) == nil then return nil end
    return keys
end

