-- Creates the window (and runs the key system first). Returns false if the key list can't be loaded.
function bearlib:Boot()
    if Created then return true end
    local keys = fetchKeys()
    if not keys then
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = HUB_NAME,
                Text = "Could not load the key list. Check your connection and re-execute.",
                Duration = 10,
            })
        end)
        warn("[" .. HUB_NAME .. "] key list could not be loaded")
        return false
    end
    Created = WindUI:CreateWindow({
        Title = HUB_NAME,
        Author = HUB_AUTHOR,
        Folder = HUB_NAME,
        Icon = "rbxassetid://11354741327",
        Theme = "Bantai",
        Transparent = true,
        Acrylic = false,
        Size = UDim2.fromOffset(600, 340),
        MinSize = Vector2.new(480, 280),
        MaxSize = Vector2.new(850, 560),
        SideBarWidth = 170,
        Radius = 14,
        HideSearchBar = true,
        OpenButton = {
            Title = HUB_NAME,
            Enabled = true,
            Draggable = true,
        },
        KeySystem = {
            Title = HUB_NAME,
            Note = "Enter your key to continue.",
            SaveKey = true,
            KeyValidator = function(key)
                return keys[trim(key)] == true
            end,
        },
    })
    return true
end

function bearlib:MakeWindow(Configs)
    Configs = Configs or {}
    if not Created and not bearlib:Boot() then
        error("Bantai Hub v2: window could not be created")
    end
    local WindUIWindow = Created

    local Window = {}

    function Window:MakeTab(TabConfigs)
        TabConfigs = TabConfigs or {}
        local TabObj = WindUIWindow:Tab({
            Title = TabConfigs.Title or TabConfigs.Name or TabConfigs[1] or "Tab",
            Icon = TabConfigs.Icon,
        })

        local Tab = {}

        function Tab:AddSection(C)
            C = type(C) == "table" and C or {C}
            local Section = TabObj:Section({
                Title = C[1] or C.Name or C.Title or "Section",
            })
            local obj = {}
            function obj:Set(New)
                if type(New) == "string" and Section and Section.SetTitle then
                    pcall(function() Section:SetTitle(New) end)
                end
            end
            function obj:Destroy() pcall(function() Section:Destroy() end) end
            return obj
        end

        function Tab:AddParagraph(C)
            C = C or {}
            local Paragraph = TabObj:Paragraph({
                Title = C.Title or C.Name or C[1] or "Paragraph",
                Desc = C.Desc or C.Content or C.Description or C[2] or "",
            })
            local lastTitle, lastDesc
            local obj = {}
            function obj:SetTitle(v)
                if v == lastTitle then return end
                lastTitle = v
                pcall(function() Paragraph:SetTitle(v) end)
            end
            function obj:SetDesc(v)
                if v == lastDesc then return end
                lastDesc = v
                pcall(function() Paragraph:SetDesc(v) end)
            end
            function obj:Set(a, b)
                if b ~= nil then obj:SetTitle(a) obj:SetDesc(b)
                elseif type(a) == "string" then obj:SetTitle(a) end
            end
            function obj:Visible() end
            function obj:Destroy() pcall(function() Paragraph:Destroy() end) end
            return obj
        end

        function Tab:AddButton(C)
            C = C or {}
            local Callback = pickCallback(C, 2)
            local Button = TabObj:Button({
                Title = C[1] or C.Name or C.Title or "Button",
                Desc = C.Desc or C.Description,
                Callback = function() Callback() end,
            })
            local obj = {}
            function obj:Callback(f) if type(f) == "function" then f() else Callback() end end
            function obj:Set(v)
                if type(v) == "function" then Callback = v
                elseif type(v) == "string" then pcall(function() Button:SetTitle(v) end) end
            end
            function obj:Visible() end
            function obj:Destroy() pcall(function() Button:Destroy() end) end
            return obj
        end

        function Tab:AddToggle(C)
            C = C or {}
            local Callback = pickCallback(C, 3)
            local Default = C[2] or C.Default or false
            local Toggle = TabObj:Toggle({
                Title = C[1] or C.Name or C.Title or "Toggle",
                Desc = C.Desc or C.Description,
                Value = Default and true or false,
                Callback = function(v) Callback(v) end,
            })
            -- the previous UI applied the default state through the callback on creation
            fire(function(v) Callback(v) end, Default and true or false)
            local obj = {}
            function obj:Set(v, v2)
                if type(v) == "boolean" then pcall(function() Toggle:Set(v) end)
                elseif type(v) == "string" then pcall(function() Toggle:SetTitle(v) end)
                    if type(v2) == "string" then pcall(function() Toggle:SetDesc(v2) end) end
                elseif type(v) == "function" then Callback = v end
            end
            function obj:Callback(f) if type(f) == "function" then f(Toggle.Value) else Callback(Toggle.Value) end end
            function obj:Visible() end
            function obj:Destroy() pcall(function() Toggle:Destroy() end) end
            return obj
        end

        function Tab:AddDropdown(C)
            C = C or {}
            local Callback = pickCallback(C, 4)
            local Values = copyList(C[2] or C.Options or {})
            local Default = C[3] or C.Default
            if type(Default) == "table" then Default = Default[1] end
            local Multi = (C.MultiSelect or C.Multi) and true or false
            local Dropdown = TabObj:Dropdown({
                Title = C[1] or C.Name or C.Title or "Dropdown",
                Desc = C.Desc or C.Description,
                Values = copyList(Values),
                Value = (not Multi) and Default or nil,
                Multi = Multi,
                Callback = function(v) Callback(v) end,
            })
            local obj = {}
            function obj:Refresh(List, Clear)
                if type(List) ~= "table" then return end
                if sameList(Values, List) then return end
                Values = copyList(List)
                pcall(function() Dropdown:Refresh(copyList(Values)) end)
            end
            function obj:Set(List, Clear)
                if type(List) == "table" then obj:Refresh(List, Clear)
                elseif type(List) == "function" then Callback = List end
            end
            function obj:Add(...)
                local new = {...}
                if type(new[1]) == "table" then new = new[1] end
                for _, v in ipairs(new) do table.insert(Values, v) end
                pcall(function() Dropdown:Refresh(copyList(Values)) end)
            end
            function obj:Remove(Option)
                for i = #Values, 1, -1 do
                    if Values[i] == Option or i == Option then table.remove(Values, i) end
                end
                pcall(function() Dropdown:Refresh(copyList(Values)) end)
            end
            function obj:Select(Option)
                if type(Option) == "number" then Option = Values[Option] end
                if Option ~= nil then pcall(function() Dropdown:Select(Option) end) end
            end
            function obj:Callback(f) if type(f) == "function" then f(Dropdown.Value) else Callback(Dropdown.Value) end end
            function obj:Visible() end
            function obj:Destroy() pcall(function() Dropdown:Destroy() end) end
            return obj
        end

        function Tab:AddSlider(C)
            C = C or {}
            local Callback = pickCallback(C, 6)
            local Min = C[2] or C.MinValue or C.Min or 10
            local Max = C[3] or C.MaxValue or C.Max or 100
            local Step = C[4] or C.Increase or C.Increment or 1
            local Default = C[5] or C.Default or 25
            Default = math.clamp(Default, Min, Max)
            local Slider = TabObj:Slider({
                Title = C[1] or C.Name or C.Title or "Slider",
                Desc = C.Desc or C.Description,
                Step = Step,
                Value = {Min = Min, Max = Max, Default = Default},
                Callback = function(v) Callback(v) end,
            })
            fire(function(v) Callback(v) end, Default)
            local obj = {}
            function obj:Set(v)
                if type(v) == "number" then pcall(function() Slider:Set(v) end)
                elseif type(v) == "string" then pcall(function() Slider:SetTitle(v) end)
                elseif type(v) == "function" then Callback = v end
            end
            function obj:Callback(f) if type(f) == "function" then f(Default) else Callback(Default) end end
            function obj:Visible() end
            function obj:Destroy() pcall(function() Slider:Destroy() end) end
            return obj
        end

        function Tab:AddTextBox(C)
            C = C or {}
            local Callback = pickCallback(C, 4)
            local Default = C[2] or C.Default
            if Default ~= nil then Default = tostring(Default) end
            local Input = TabObj:Input({
                Title = C[1] or C.Name or C.Title or "Text Box",
                Desc = C.Desc or C.Description,
                Placeholder = C[5] or C.Placeholder or C.PlaceHolder or C.PlaceholderText or "Input",
                Value = Default or "",
                ClearTextOnFocus = (C[3] or C.ClearText or C.ClearOnFocus) and true or false,
                Callback = function(v) Callback(v) end,
            })
            local obj = {}
            function obj:Set(v)
                if type(v) == "string" then pcall(function() Input:Set(v) end) end
            end
            function obj:Visible() end
            function obj:Destroy() pcall(function() Input:Destroy() end) end
            return obj
        end

        return Tab
    end

    function Window:SelectTab() end
    function Window:Destroy() pcall(function() WindUIWindow:Destroy() end) end
    function Window:Dialog() end

    return Window
end

return bearlib

end)()
