-- RegisterAttack/RegisterHit combat helper.
-- Uses cached remotes and a small per-target cooldown to avoid unnecessary remote spam.
-- RegisterAttack/RegisterHit must be resolved after the game services are available.
-- Do not cache them from the earlier global initialization block: that block runs later.
local function GetRegisterHitRemotes()
    local rs = game:GetService("ReplicatedStorage")
    local modules = rs:FindFirstChild("Modules")
    local net = modules and modules:FindFirstChild("Net")
    if not net then
        return nil, nil, nil
    end

    local registerAttack = net:FindFirstChild("RE/RegisterAttack")
    local registerHit = net:FindFirstChild("RE/RegisterHit")

    if not registerAttack then
        pcall(function()
            registerAttack = net:WaitForChild("RE/RegisterAttack", 5)
        end)
    end
    if not registerHit then
        pcall(function()
            registerHit = net:WaitForChild("RE/RegisterHit", 5)
        end)
    end

    return net, registerAttack, registerHit
end

local function BuildHitParts(targets)
    local parts = {}
    local firstPart = nil

    for _, entry in ipairs(targets or {}) do
        local model = entry[1]
        local preferred = entry[2]

        if model and model.Parent then
            local addedPreferred = false
            if preferred and preferred:IsA("BasePart") and preferred:IsDescendantOf(model) then
                parts[#parts + 1] = {model, preferred}
                firstPart = firstPart or preferred
                addedPreferred = true
            end

            if not addedPreferred then
                local head = model:FindFirstChild("Head")
                if head and head:IsA("BasePart") then
                    parts[#parts + 1] = {model, head}
                    firstPart = firstPart or head
                end
            end

            for _, part in ipairs(model:GetChildren()) do
                if part:IsA("BasePart") and part ~= preferred and part.Name ~= "Head" then
                    parts[#parts + 1] = {model, part}
                end
            end
        end
    end

    return firstPart, parts
end

local CachedHitRemote = nil
local CachedHitRemoteId = nil

local function FindHitFallbackRemote()
    if CachedHitRemote and CachedHitRemote.Parent then
        return CachedHitRemote, CachedHitRemoteId
    end

    local containers = {
        game:GetService("ReplicatedStorage"):FindFirstChild("Util"),
        game:GetService("ReplicatedStorage"):FindFirstChild("Common"),
        game:GetService("ReplicatedStorage"):FindFirstChild("Remotes"),
        game:GetService("ReplicatedStorage"):FindFirstChild("Assets"),
        game:GetService("ReplicatedStorage"):FindFirstChild("FX")
    }

    for _, container in ipairs(containers) do
        if container then
            for _, child in ipairs(container:GetChildren()) do
                if child:IsA("RemoteEvent") and child:GetAttribute("Id") then
                    CachedHitRemote = child
                    CachedHitRemoteId = child:GetAttribute("Id")
                    return CachedHitRemote, CachedHitRemoteId
                end
            end
        end
    end

    return nil, nil
end

local function FireFallbackRegisterHit(net, hitPart, hitTargets)
    local remote, remoteId = FindHitFallbackRemote()
    if not remote or type(remoteId) ~= "number" or type(bit32) ~= "table"
        or type(bit32.bxor) ~= "function" then
        return
    end

    local seedRemote = net and net:FindFirstChild("seed")
    local seed
    if seedRemote and seedRemote:IsA("RemoteFunction") then
        pcall(function()
            seed = seedRemote:InvokeServer()
        end)
    end
    if type(seed) ~= "number" then
        return
    end

    local okClone, clonedRemote = pcall(function()
        if type(cloneref) == "function" then
            return cloneref(remote)
        end
        return remote
    end)
    if not okClone or not clonedRemote then
        clonedRemote = remote
    end

    pcall(function()
        local key = math.floor(workspace:GetServerTimeNow() / 10 % 10) + 1
        local encoded = string.gsub("RE/RegisterHit", ".", function(c)
            return string.char(bit32.bxor(string.byte(c), key))
        end)

        clonedRemote:FireServer(
            encoded,
            bit32.bxor(remoteId + 909090, seed * 2),
            hitPart,
            hitTargets
        )
    end)
end

local function RegisterHitAttack(target)
    if not target then
        return false
    end

    local hum = target:FindFirstChildOfClass("Humanoid") or target:FindFirstChild("Humanoid")
    if not hum or hum.Health <= 0 then
        return false
    end

    local head = target:FindFirstChild("Head")
    local root = target:FindFirstChild("HumanoidRootPart")
    local hitPart = (head and head:IsA("BasePart") and head) or root
    if not hitPart then
        return false
    end

    local net, registerAttack, registerHit = GetRegisterHitRemotes()
    if not net or not registerAttack or not registerHit then
        return false
    end

    local firstPart, hitTargets = BuildHitParts({{target, hitPart}})
    firstPart = firstPart or hitPart
    if #hitTargets == 0 then
        hitTargets = {{target, hitPart}}
    end

    -- Match the working attack implementation: initialize RegisterHit,
    -- register the attack first, then send the complete hit-parts payload.
    pcall(function()
        local netRequire = require(net)
        if type(netRequire) == "table" and type(netRequire.RemoteEvent) == "function" then
            netRequire:RemoteEvent("RegisterHit", true)
        end
    end)

    local player = game:GetService("Players").LocalPlayer
    local attackId = tostring(player and player.UserId or 0):sub(2, 4)
        .. tostring(coroutine.running()):sub(11, 15)

    local ok = false
    for _ = 1, math.max(1, tonumber(_G.AttackMultiplier) or 1) do
        local success = pcall(function()
            registerAttack:FireServer()
            registerHit:FireServer(firstPart, hitTargets, {}, attackId)
            FireFallbackRegisterHit(net, firstPart, hitTargets)
        end)
        ok = ok or success
    end

    return ok
end


G.Kill = function(I, e)
    if not (I and e) then return end

    local hrp = I:FindFirstChild("HumanoidRootPart")
    local hum = I:FindFirstChild("Humanoid")
    if not hrp or not hum or hum.Health <= 0 then return end

    -- Lock the target position for the bring system.
    if not I:GetAttribute("Locked") then
        I:SetAttribute("Locked", hrp.CFrame)
    end

    PosMon = (I:GetAttribute("Locked")).Position

    -- Keep the existing bring behavior.
    _B = true
    BringEnemy()

    -- Equip the selected weapon before registering the hit.
    EquipWeapon(_G.SelectWeapon)

    local tool = game.Players.LocalPlayer.Character
        and game.Players.LocalPlayer.Character:FindFirstChildOfClass("Tool")
    if not tool then return end

    -- Move above the target, then use the game's register-hit remotes.
    _tp(hrp.CFrame * CFrame.new(0, _G.MobHeight, 0))
    RegisterHitAttack(I)
end
