-- =======================
-- distance-adjusted tween
-- =======================

-- [[ TWEEN SETTINGS ]] --
getgenv().TweenSpeedFar = 300
getgenv().TweenSpeedNear = 900

-- NoClip is enabled only while a player tween is actually running.
local TweenNoClipActive = false
local TweenNoClipCache = {}
local TweenSerial = 0
local ActivePlayerTween = nil

local function SetTweenNoClip(enabled)
    local character = plr.Character
    if not character then return end

    if enabled then
        if TweenNoClipActive then return end
        TweenNoClipActive = true
        TweenNoClipCache = {}

        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") then
                TweenNoClipCache[part] = part.CanCollide
                part.CanCollide = false
            end
        end
    elseif TweenNoClipActive then
        TweenNoClipActive = false

        for part, oldCanCollide in pairs(TweenNoClipCache) do
            if part and part.Parent then
                part.CanCollide = _G.NoClip and false or oldCanCollide
            end
        end

        table.clear(TweenNoClipCache)
    end
end

_tp = function(I)
    local character = plr.Character
    if not character or not character:FindFirstChild("HumanoidRootPart") or not I then
        return
    end

    local HRP = character.HumanoidRootPart
    TweenSerial += 1
    local myTweenSerial = TweenSerial

    -- Cancel the previous player tween, but keep NoClip active for the new tween.
    if ActivePlayerTween and ActivePlayerTween.PlaybackState == Enum.PlaybackState.Playing then
        pcall(function()
            ActivePlayerTween:Cancel()
        end)
    end

    shouldTween = true
    getgenv().OnFarm = false
    SetTweenNoClip(true)

    if HRP.Anchored then
        HRP.Anchored = false
        task.wait()
    end

    local dist = (I.Position - HRP.Position).Magnitude
    local speed = dist <= 90
        and (getgenv().TweenSpeedNear or 900)
        or (getgenv().TweenSpeedFar or 300)

    if dist <= 0.5 then
        HRP.CFrame = I
        if myTweenSerial == TweenSerial then
            SetTweenNoClip(false)
            getgenv().OnFarm = true
        end
        return
    end

    local info = TweenInfo.new(
        math.max(dist / math.max(speed, 1), 0.03),
        Enum.EasingStyle.Linear,
        Enum.EasingDirection.Out
    )

    local tween = TW:Create(C, info, {CFrame = I})
    ActivePlayerTween = tween

    if character.Humanoid and character.Humanoid.Sit then
        C.CFrame = CFrame.new(C.Position.X, I.Y, C.Position.Z)
    end

    tween:Play()

    task.spawn(function()
        while tween.PlaybackState == Enum.PlaybackState.Playing do
            if not shouldTween or myTweenSerial ~= TweenSerial then
                pcall(function()
                    tween:Cancel()
                end)
                break
            end
            task.wait(0.05)
        end

        if myTweenSerial == TweenSerial then
            ActivePlayerTween = nil
            SetTweenNoClip(false)
            getgenv().OnFarm = true
        end
    end)
end

TeleportToTarget = function(I)
_tp(I)
end

notween = function(I)
plr.Character.HumanoidRootPart.CFrame = I
end


