-- define the distance threshold for conditional teleportation (studs)
local TELEPORT_DISTANCE_THRESHOLD = 15 

-- helper function for conditional teleportation
local function TeleportConditional(hrp, targetCFrame, threshold)
    if not hrp or not targetCFrame then return end
    
    local dist = (targetCFrame.Position - hrp.Position).Magnitude  
    if dist > threshold then  
        _tp(targetCFrame)  
    end
end

