local SelectedMelee = "Dark Step"

-- get Melee available in the current Sea
local function GetAvailableMeleeOptions()
    local list = {}
    for name, data in pairs(MeleeCoords) do
        if data.Pos then 
            table.insert(list, name) 
        end
    end
    table.sort(list)
    return list
end

-- Melee selection dropdown
v14:AddDropdown({
    Name = "Select Melee to Buy",
    Options = GetAvailableMeleeOptions(),
    Default = "Dark Step",
    Callback = function(Value)
        SelectedMelee = Value
    end
})

-- Auto Buy Melee Toggle
v14:AddToggle({
    Name = "Auto Buy (On/Off)",
    Default = GetSetting("AutoBuyMelee_Save", false),
    Callback = function(Value)
        _G.AutoBuyMelee = Value
        _G.SaveData["AutoBuyMelee_Save"] = Value
        MarkConfigDirty()
        
        -- NOCLIP MANAGEMENT
        if Value then
            _G.MeleeNoclip = game:GetService("RunService").Stepped:Connect(function()
                if not _G.AutoBuyMelee then 
                    if _G.MeleeNoclip then _G.MeleeNoclip:Disconnect() end
                    return 
                end
                local char = game.Players.LocalPlayer.Character
                if char then
                    for _, v in pairs(char:GetDescendants()) do
                        if v:IsA("BasePart") and v.CanCollide then
                            v.CanCollide = false
                        end
                    end
                end
            end)
        else
            if _G.MeleeNoclip then 
                _G.MeleeNoclip:Disconnect()
                _G.MeleeNoclip = nil
            end
            local char = game.Players.LocalPlayer.Character
            if char then
                for _, v in pairs(char:GetDescendants()) do
                    if v:IsA("BasePart") then v.CanCollide = true end
                end
            end
        end

        -- MAIN LOGIC
        task.spawn(function()
            while _G.AutoBuyMelee do
                task.wait()
                if not _G.AutoBuyMelee then break end

                local data = MeleeCoords[SelectedMelee]
                if not data or not data.Pos then
                    bearlib:Notify({
                        Title = "Bantai Hub v2",
                        Message = "Error: No location found for this Melee in the current Sea!",
                        Duration = 3
                    })
                    _G.AutoBuyMelee = false
                    break
                end

                local lp = game.Players.LocalPlayer
                if lp.Character and lp.Character:FindFirstChild("HumanoidRootPart") then
                    local hrp = lp.Character.HumanoidRootPart
                    local dist = (hrp.Position - data.Pos.Position).Magnitude

                    if dist > 15 then
                        -- use the _tp function from the text file
                        _tp(data.Pos)
                    else
                        -- stop the tween if it is running
                        shouldTween = false
                        hrp.CFrame = data.Pos
                        
                        -- Buy Melee
                        game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer(data.Key)
                        game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("BuyItem", data.Key)
                        
                        bearlib:Notify({
                            Title = "Bantai Hub v2",
                            Message = "Purchased: " .. SelectedMelee,
                            Duration = 2
                        })
                        task.wait(1)
                    end
                end
            end
        end)
    end
})

