v12:AddSection({"Speed/Jump"})

-- GET VALUES FROM GRAVITY HUB
-- Gravity Hub uses:
-- English comment: (getgenv()).WalkSpeedValue = 30 (mc nh)
-- English comment: (getgenv()).JumpValue = 50 (mc nh)
-- English comment: _G.WalkSpeedEnabled  bt/tt
-- English comment: _G.JumpEnabled  bt/tt

-- speed control variables (synced with Gravity Hub)
_G.WalkSpeedEnabled = _G.WalkSpeedEnabled or false
_G.JumpEnabled = _G.JumpEnabled or false
(getgenv()).WalkSpeedValue = (getgenv()).WalkSpeedValue or 30
(getgenv()).JumpValue = (getgenv()).JumpValue or 50

-- English comment: Hm p dng stats (copy from Gravity Hub)
local function applyStats()
    local char = game.Players.LocalPlayer.Character
    if char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            if _G.WalkSpeedEnabled then
                hum.WalkSpeed = (getgenv()).WalkSpeedValue
            end
            if _G.JumpEnabled then
                hum.JumpPower = (getgenv()).JumpValue
            end
        end
    end
end

-- watch WalkSpeed changes (same as Gravity Hub)
local function setupSpeedWatcher(hum)
    if hum then
        hum:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
            if _G.WalkSpeedEnabled and hum.WalkSpeed ~= (getgenv()).WalkSpeedValue then
                hum.WalkSpeed = (getgenv()).WalkSpeedValue
            end
        end)
    end
end

-- English comment: Theo di thay i nhn vt (ging Gravity Hub)
local plr = game.Players.LocalPlayer
plr.CharacterAdded:Connect(function(char)
    char:WaitForChild("Humanoid")
    applyStats()
    setupSpeedWatcher(char:FindFirstChildOfClass("Humanoid"))
end)

-- apply immediately if a character already exists
if plr.Character then
    local hum = plr.Character:FindFirstChildOfClass("Humanoid")
    if hum then
        applyStats()
        setupSpeedWatcher(hum)
    end
end

-- monitor loop (kept from text file 1.txt)
game:GetService("RunService").Heartbeat:Connect(applyStats)

