v12:AddToggle({
    Name = "Accept Allies",
    Default = GetSetting("AcceptAlly_Save", false),
    Callback = function(value)
        _G.AcceptAlly = value
        _G.SaveData["AcceptAlly_Save"] = value
        MarkConfigDirty()
        
        task.spawn(function()
            while _G.AcceptAlly do
